#!/usr/bin/env bash
# Tribute · publish the newest TTS export (generated by "Tribute - TTS Export").
# Run from Git Bash:   cd ~/tribute-tts && ./publish.sh
set -e
cd "$(dirname "$0")"
ZIP=$(ls -t "$HOME"/Downloads/tribute-tts-export*.zip 2>/dev/null | head -n 1)
if [ -z "$ZIP" ]; then echo "No tribute-tts-export zip found in Downloads."; exit 1; fi
echo "Unpacking: $(basename "$ZIP")"
if command -v unzip >/dev/null 2>&1; then
  unzip -o -q "$ZIP" -d .
else
  powershell.exe -NoProfile -Command "Expand-Archive -Force -LiteralPath '$(cygpath -w "$ZIP")' -DestinationPath '$(cygpath -w "$PWD")'"
fi
git add -A
if git diff --cached --quiet; then
  echo "Nothing changed since the last publish."
else
  git commit -q -m "Publish $(date '+%Y-%m-%d %H:%M')"
  echo "Pushing to GitHub..."
  git push -q
  echo "Published."
fi
SAVED=0
for D in "$HOME/Documents/My Games/Tabletop Simulator/Saves" "$HOME/OneDrive/Documents/My Games/Tabletop Simulator/Saves"; do
  if [ -d "$D" ]; then
    cp -f Tribute.json "$D/TS_Save_7700.json"
    cp -f Tribute.png "$D/TS_Save_7700.png" 2>/dev/null || true
    echo "Save installed: $D/TS_Save_7700.json"
    SAVED=1
  fi
done
if [ "$SAVED" = "0" ]; then echo "Could not find your TTS Saves folder. Copy Tribute.json there by hand, renamed to TS_Save_7700.json."; fi
echo "Done. In TTS: Games > Save & Load > Tribute."
